def transform(grid):
    g=[r[:] for r in grid]
    h,w=len(g),len(g[0])
    # detect non-background colors differing from dominant tile background; connect aligned regions' centers in separator bands
    # identify grid tile centers by colored nonzero cells, anomalies are colors other than frame color 4
    # for each color other than 0,4 find rows/cols containing its cells and bridge between bounding anomaly blocks when aligned.
    for color in set(v for row in g for v in row)-{0,4}:
        cells=[(r,c) for r in range(h) for c in range(w) if g[r][c]==color]
        # use contiguous blocks of this color and connect their centers when same row-band / col-band
        # typical tile anomaly blocks are rectangular; derive centers from connected components
        seen=set(); comps=[]
        for p in cells:
            if p in seen: continue
            stack=[p]; seen.add(p); cc=[]
            while stack:
                r,c=stack.pop(); cc.append((r,c))
                for q in ((r+1,c),(r-1,c),(r,c+1),(r,c-1)):
                    if 0<=q[0]<h and 0<=q[1]<w and q not in seen and g[q[0]][q[1]]==color:
                        seen.add(q); stack.append(q)
            comps.append((sum(r for r,c in cc)//len(cc),sum(c for r,c in cc)//len(cc)))
        # bridge only when centers aligned and separated; across blank gaps, not over intervening tile content
        for i,(r,c) in enumerate(comps):
            for rr,cc in comps[i+1:]:
                if r==rr:
                    for x in range(min(c,cc)+1,max(c,cc)):
                        if g[r][x]==0: g[r][x]=color
                if c==cc:
                    for y in range(min(r,rr)+1,max(r,rr)):
                        if g[y][c]==0: g[y][c]=color
    return g
