    rstarts=[r for r in range(h) if any(grid[r][c]==4 for c in range(w)) and (r==0 or not any(grid[r-1][c]==4 for c in range(w)))]
    cstarts=[c for c in range(w) if any(grid[r][c]==4 for r in range(h)) and (c==0 or not any(grid[r][c-1]==4 for r in range(h)))]
    # use known observed regular spacing, with starts at first frame occurrence
    rstarts=[]; cstarts=[]
